// Curated polite (ます) forms for verbs among N5 and N4 deck example words.
// Hand-written and verified (not generated by scripts/fetch-data.mjs).
// Only true verbs are listed — nouns, counters (一つ), and adjectives (高い)
// are intentionally omitted. Godan-ru verbs are handled correctly
// (知る → 知ります, 帰る → 帰ります, 入る → 入ります), as are the irregulars
// 来る → 来ます. Words not listed here simply have no polite form to show.

export interface MasuForm {
  /** Polite form in kanji, e.g. 出ます */
  masu: string
  /** Polite form in hiragana, e.g. でます */
  masuReading: string
}

